<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/auth.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/payments.php';
$current=tuman_require_role('TEACHER');$db=tuman_database();$invoices=tuman_teacher_payment_invoices($db,$current['id']);$statement=$db->prepare('SELECT p.*,i.invoice_number,i.currency_code,sp.first_name,sp.last_name FROM tmn_payments p INNER JOIN tmn_invoices i ON i.id=p.invoice_id INNER JOIN tmn_teacher_students ts ON ts.id=i.teacher_student_id INNER JOIN tmn_student_profiles sp ON sp.user_id=ts.student_user_id WHERE ts.teacher_user_id=:teacher_id ORDER BY p.payment_date DESC,p.id DESC');$statement->execute(['teacher_id'=>$current['id']]);$payments=$statement->fetchAll();tuman_teacher_page_start('Payments');
?>
<h1>Payments</h1><p><a class="button" href="/Tuman/teacher/payment-create.php">Record payment</a></p><div style="overflow-x:auto"><table><thead><tr><th>Invoice</th><th>Student</th><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><td><?= htmlspecialchars($payment['invoice_number'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars(trim($payment['first_name'].' '.($payment['last_name']??'')),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['payment_date'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars(tuman_invoice_money_label($payment['amount'],$payment['currency_code']),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['payment_method'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['reference_number']??'—',ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($payment['status'],ENT_QUOTES,'UTF-8') ?><?= $payment['voided_at']?' '.$payment['voided_at']:'' ?></td><td><?php if($payment['status']==='VALID'): ?><a href="/Tuman/teacher/payment-void.php?id=<?= (int)$payment['id'] ?>">Void</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($payments===[]): ?><p>No payments recorded.</p><?php endif; ?>
<?php tuman_teacher_page_end(); ?>
